def minKWindowFlips(nums, k):
    n = len(nums)
    end = [0] * (n + 1)
    parity = 0
    flips = 0
    for i in range(n):
        parity ^= end[i]
        if nums[i] ^ parity == 0:
            if i + k > n:
                return -1
            flips += 1
            parity ^= 1
            end[i + k] ^= 1
    return flips
